$("body").on("click","#city-picker",function(){if(!$(".pac-container").length){placesAutocomplete()}}).on("click",".call-city-picker",function(){$("#navigation").removeClass("pushed").removeClass("opened");$("#city-picker").modal("show")}).on("click",".set-city",function(){$(".set-city").removeClass("active");$(this).addClass("active");setLocation($(this).data("city"))});$(function(){$.ajax({type:"POST",url:"/citydetector/ajax/load-modal",data:{},success:function(a){$("body").append(a)},error:function(a){console.log(a)}})});function setLocation(a){$.ajax({type:"POST",url:"/citydetector/ajax/set-location",data:{input:a},success:function(b){$(".location-city").text(b).val(b);$("#city-picker").modal("hide");location.reload()},error:function(b){console.log(b)}})}function placesAutocomplete(){var a=document.getElementById("city-picker-input");var b={types:["(cities)"],componentRestrictions:{country:"ru"}};autocomplete=new google.maps.places.Autocomplete(a,b);google.maps.event.addListener(autocomplete,"place_changed",function(){$(".set-city").removeClass("active");setLocation($("#city-picker-input").val())})};